#[no_mangle]
pub extern "C" fn feistel_cipher_normalized(a:*const i64,n:usize)->i64{if a.is_null()||n!=3{return -1}let v=unsafe{std::slice::from_raw_parts(a,n)};if !(0..=1).contains(&v[0])||v[1]<1||v[1]>u32::MAX as i64{return -1}let key=v[1] as u32;if (0..32).any(|i| rk(key,i)==0){return -1}let b=v[2] as u64;let(mut l,mut r)=((b>>32)as u32,b as u32);fn rk(k:u32,round:u32)->u32{let mut p=1u32;for _ in 0..round+2{p=p.wrapping_mul(k)}p^k}fn f(mut x:u32,k:u32)->u32{for _ in 0..32{x=(x^0x55555555).wrapping_mul(x)%k;x^=k}x}if v[0]==0{for i in 0..32{let t=r^f(l,rk(key,i));r=l;l=t}}else{for i in (0..32).rev(){let t=l^f(r,rk(key,i));l=r;r=t}}(((l as u64)<<32)|r as u64) as i64}
